import type { SkeletonProps } from "./skeleton.types";

import { cloneElement, forwardRef, isValidElement, useLayoutEffect, useRef, useState } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";

import { SkeletonClasses, StyledSkeleton } from "./skeleton.styles";

const Skeleton = forwardRef<HTMLDivElement, SkeletonProps>(
  (
    { children, variant, className, style, shape = "square", size, loading = true, ...props },
    ref,
  ) => {
    const childRef = useRef<HTMLElement>(null);
    const appliedSize = size ?? "lg";
    const [borderRadius, setBorderRadius] = useState<React.CSSProperties["borderRadius"]>();
    const [childWidth, setChildWidth] = useState<React.CSSProperties["width"]>();
    const [childHeight, setChildHeight] = useState<React.CSSProperties["height"]>();
    const theme = useTheme();
    const rootClasses = clsx(
      SkeletonClasses.root,
      {
        [SkeletonClasses[shape]]: shape,
        [SkeletonClasses[appliedSize]]: appliedSize,
      },
      className,
    );

    // Measure the child element (if any) to adopt its dimensions & border radius
    useLayoutEffect(() => {
      // if we're given a size prop, we don't need to measure the child
      if (childRef.current && !size) {
        const childComputedStyle = window.getComputedStyle(childRef.current);
        const { borderRadius: br, width: w, height: h } = childComputedStyle;
        if (br && br !== "0px") setBorderRadius(br);
        if (w && w !== "0px" && w !== "auto") setChildWidth(w);
        if (h && h !== "0px" && h !== "auto") setChildHeight(h);
      }
    }, [children, size]);

    const childWithRef = isValidElement(children)
      ? cloneElement(children as React.ReactElement, {
          ref: childRef,
        })
      : children;

    if (!loading) return <>{children}</>;

    return (
      <StyledSkeleton
        ref={ref}
        className={rootClasses}
        currentTheme={theme}
        style={{
          borderRadius,
          // Explicit style prop values take precedence over measured values
          height: style?.height ?? childHeight,
          width: style?.width ?? childWidth,
          ...style,
        }}
        variant={variant}
        {...props}
      >
        <span
          aria-hidden="true"
          // @ts-expect-error - Allow inert attribute until React types include it officially
          inert="true"
        >
          {childWithRef}
        </span>
      </StyledSkeleton>
    );
  },
);

Skeleton.displayName = "Skeleton";

export default Skeleton;
